// Some portions generated by Claude
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.junit.jupiter.api.Test;

/**
 * A pure insertion only acquires a read view when connection listeners need duplicate detection. The listener state
 * must be sampled once per call: a listener registered concurrently must not make the notification path dereference the
 * read view that was skipped a moment earlier.
 */
class MemoryStoreConnectionListenerRaceTest {

	@Test
	void addStatementSamplesListenerStateOnceWhenSkippingTheReadView() {
		MemoryStore store = new MemoryStore();
		store.init();
		ValueFactory vf = store.getValueFactory();
		IRI subject = vf.createIRI("urn:listener-race:subject");
		IRI predicate = vf.createIRI("urn:listener-race:predicate");
		IRI object = vf.createIRI("urn:listener-race:object");
		AtomicInteger listenerChecks = new AtomicInteger();
		try (MemoryStoreConnection connection = new MemoryStoreConnection(store) {
			@Override
			protected boolean hasConnectionListeners() {
				// The first check decides that the insertion needs no read view; a listener registered right after
				// that decision makes every later check observe listeners.
				return listenerChecks.getAndIncrement() > 0;
			}
		}) {
			connection.begin();
			connection.addStatement(subject, predicate, object);
			connection.commit();
			assertTrue(connection.hasStatement(subject, predicate, object, false));
		} finally {
			store.shutDown();
		}
	}
}
